-- stage2 -> L0, page_tag = srp & sdp & sup & image_search
---------------------------------------------------------------------------------------
--
--sql_divide_splitter--
create temporary view l0_search_page_duration_di_${grass_region_without_quote} as
select grass_region
      ,event_id
      ,user_id
      ,page_duration as duration  -- ms
      ,case
         when page_type = 'search' and search_args.scenario_key in ('PAGE_GLOBAL_SEARCH', 'PAGE_PDP_SEARCH', 'PAGE_PREFILL_SEARCH') then 'srp'
         when page_type = 'pre_search' then 'sdp'
         when page_type = 'search_suggest_page' then 'sup'
         when page_type = 'image_search' then 'image_search'
      end as page_tag
from traffic.dwd_view_di__reg_live
where grass_date = ${local_date}
and grass_region in (${grass_region})
and tz_type = 'local'
and os in ('ios', 'android')
and user_id > 0
and (
        (page_type = 'search' and search_args.scenario_key in ('PAGE_GLOBAL_SEARCH', 'PAGE_PDP_SEARCH', 'PAGE_PREFILL_SEARCH')) -- srp
     or
        (page_type in ('pre_search'           -- sdp
                      ,'search_suggest_page'  -- sup
                      ,'image_search')        -- image_search
        )
)
;

