-- stage1 click source - L1, click为主表
---------------------------------------------------------------------------------------
create temporary view orig_dd_search_click_event_${grass_region_without_quote} as
select grass_region
      ,user_id
      ,event_id
      ,log_timestamp as click_timestamp
      ,target_type as card_type

      ,if(original_page_type = 'home', 'dd', 'search') as scenario_tag
      ,request_id
      ,item_id

      ,case
         when target_type in ('item', 'item_mix_feed_card') then item_id
         when target_type in ('video', 'livestream') then cast(content_id as bigint)
         when original_page_type = 'search' and target_type = 'ai_minifeed_card' then null
       end as card_id

      ,location

      ,case
         when original_page_type = 'home' and page_section[0] = 'daily_discover' and target_type = 'livestream' then cast(content_id as bigint) -- 导流到ls没有sv_source_item_id, 使用 streaming_id作为兜底关联键
         when original_page_type = 'search' and page_section[0] is null and target_type = 'ai_minifeed_card' then 0  -- srp minifeed 不上报item_id, 使用 0 作为兜底关联键
         else item_id
       end as join_content_id

      ,case
         when original_page_type = 'home' and page_section[0] = 'daily_discover' and target_type = 'livestream' then 0 -- 导流到ls没解析到 sv_source_location, 使用0作为兜底关联键
         else location
       end as join_location

      ,case
          when original_page_type = 'home' and page_section[0] = 'daily_discover' and target_type in ('video', 'livestream', 'item', 'item_mix_feed_card') then 'dd'
          when original_page_type = 'search' and page_section[0] is null and target_type in ('video', 'livestream', 'item', 'ai_minifeed_card') then 'srp'
          when original_page_type = 'image_search' and page_section[0] = 'search' and target_type = 'item' then 'image_search'
       end as source1_page_tag
from srdi_mart.dwd_sr_data_warehouse_platform
where grass_region in (${grass_region})
and local_date = ${local_date}
and operation = 'click'
and original_operation = 'click'
and platform in ('ios_app', 'android_app', 'android_app_lite')
and user_id > 0
and (
         (original_page_type = 'home' and page_section[0] = 'daily_discover' and target_type in ('video', 'livestream', 'item', 'item_mix_feed_card'))
      or
         (original_page_type = 'search' and page_section[0] is null and target_type in ('video', 'livestream', 'item', 'ai_minifeed_card'))
      or
         (original_page_type = 'image_search' and page_section[0] = 'search' and target_type = 'item')
)
;

---------------------------------------------------------------------------------------
-- stage2 导流到pdp, 可以通过 pre_click_event_id 逆向关联
---------------------------------------------------------------------------------------
--
--sql_divide_splitter--
create temporary view l1_sr_pdp_page_duration_di_${grass_region_without_quote} as -- page_tag = pdp, source1_page_tag = dd & srp & image_search & live & video
select grass_region
      ,pre_click_event_id
      ,0 as internal_location
      ,sum(duration) as duration -- 主键检索有重复, 默认sum
      ,'pdp' as page_tag
      ,max(source1_page_tag) as source1_page_tag
from (
    select grass_region
          ,position_info.pre_click_event_id as pre_click_event_id
          ,cast(page_duration as double) as duration  -- ms
          ,case
             when pre_position_code like 'home.daily_discover%' then 'dd'
             when pre_position_code like 'search.%' and pre_property.search_args.scenario_key in ('PAGE_GLOBAL_SEARCH', 'PAGE_PDP_SEARCH', 'PAGE_PREFILL_SEARCH') then 'srp'
             when pre_position_code like 'image_search.%' then 'image_search'
           end source1_page_tag
    from traffic.dwd_view_di__reg_live
    where grass_date = ${local_date}
    and grass_region in (${grass_region})
    and tz_type = 'local'
    and os in ('ios', 'android')
    and user_id > 0
    and page_type = 'product'
    and coalesce(position_info.pre_click_event_id, '') <> ''
    and (
            pre_position_code like 'home.daily_discover%' -- DD
         or
            (pre_position_code like 'search.%' and pre_property.search_args.scenario_key in ('PAGE_GLOBAL_SEARCH', 'PAGE_PDP_SEARCH', 'PAGE_PREFILL_SEARCH'))  -- srp
         or
            pre_position_code like 'image_search.%' -- image_search
    )
) t
group by grass_region, pre_click_event_id
;

---------------------------------------------------------------------------------------
-- stage3 类似逻辑近似的 video, minifeed, live 导流页
---------------------------------------------------------------------------------------
--
--sql_divide_splitter--
create temporary view l1_sr_video_page_duration_di_${grass_region_without_quote} as -- page_tag = video, source1_page_tag = dd & srp
select grass_region
       -- ,cast(sv_source_array[0] as bigint) as user_id
      ,cast(sv_source_array[2] as bigint) as location

      ,case
         when source1_page_tag = 'dd' then split(sv_source_array[3], '\\:')[0]
         when source1_page_tag = 'srp' then sv_source_array[3]
       end as request_id

      ,cast(sv_source_array[7] as bigint) as internal_location
      ,cast(sv_source_array[8] as bigint) as content_id
      ,duration
      ,'video' as page_tag
      ,source1_page_tag
from (
    select grass_region
          ,split(sv_source_entry_click_id, '\\|') as sv_source_array
            -- sv_source_entry_click_id => 0-user_id, 1-sv_source_page, 2-sv_source_location, 3-sv_source_request_id, 4-content_type, 5-content_id, 6-request_id, 7-index, 8-sv_source_item_id, 9-sv_source_video_id

          ,cast(watch_duration_ntl as double) as duration -- bigint ms
          ,case sv_source_page
             when 'iaa_dd_video_card' then 'dd'
             when 'iaa_srp_video_card' then 'srp'
           end as source1_page_tag
    from video.video_mart_dws_user_watch_time_ntl_1d
    where grass_date = ${local_date}
    and grass_region in (${grass_region})
    and sv_source_page in ('iaa_dd_video_card', 'iaa_srp_video_card')
) t
where coalesce(sv_source_array[3], '') <> ''  -- sv_source_request_id <> ''
and cast(sv_source_array[8] as bigint) > 0
;

--sql_divide_splitter--
create temporary view l1_sr_minifeed_page_duration_di_${grass_region_without_quote} as -- page_tag = minifeed, source1_page_tag = dd & srp
select grass_region
      ,sv_source_request_id as request_id
      ,case
         when position_current_page = 'srp_ai_card_page' and sv_source_page = 'iaa_srp_ai_card' then 0 -- 当前埋点上报sv_source_item_id, 但是前端click item_id没有上报, 因为使用兜底关联键
         when position_current_page = 'mix_feed_page' and sv_source_page = 'iaa_dd_mix_item' then sv_source_item_id
       end as content_id
      ,sv_source_location as location
      ,location as internal_location
      ,cast(seg_duration as double) as duration
      ,'minifeed' as page_tag
      ,case
         when position_current_page = 'mix_feed_page' and sv_source_page = 'iaa_dd_mix_item' then 'dd'
         when position_current_page = 'srp_ai_card_page' and sv_source_page = 'iaa_srp_ai_card' then 'srp'
       end as source1_page_tag
from srdi_mart.dwd_sr_data_warehouse_platform
where local_date = ${local_date}
and grass_region in (${grass_region})
and operation = 'click'
and original_operation = 'action_video'
and original_page_type = 'video'
and target_type = 'card_stay_time'
and coalesce(sv_source_request_id, '') <> ''
and (
        (position_current_page = 'mix_feed_page' and sv_source_page = 'iaa_dd_mix_item')
     or
        (position_current_page = 'srp_ai_card_page' and sv_source_page = 'iaa_srp_ai_card')
)
;

--sql_divide_splitter--
create temporary view l1_sr_live_page_duration_di_${grass_region_without_quote} as -- page_tag = live, source1_page_tag = dd & srp
select t1.grass_region
      ,t1.request_id
      ,t1.content_id
      ,t1.location
      ,t1.internal_location
      ,cast(t2.duration_b_ms as double) as duration

      ,'live' as page_tag
      ,t1.source1_page_tag
from (
    select grass_region
          ,event_id
          ,request_id
          ,cast(content_id as bigint) as content_id     --  streaming_id
          ,0 as location
          ,coalesce(location, content_location) as internal_location
          ,'dd' as source1_page_tag
    from srdi_mart.dwd_sr_data_warehouse_platform
    where local_date = ${local_date}
    and grass_region in (${grass_region})
    and operation = 'view'
    and original_page_type = 'streaming_room'
    and from_source = 'dd_card'
    and coalesce(request_id, '') <> ''
    and cast(content_id as bigint) > 0
    and coalesce(location, content_location) = 0 -- 后续新埋点发布之后, 去掉这个限定

    union all
    select grass_region
          ,event_id
          ,live_in_search_request_id as request_id
          ,live_in_search_item_id as content_id
          ,live_in_search_location as location
          ,coalesce(location, content_location) as internal_location
          ,'srp' as source1_page_tag
    from srdi_mart.dwd_sr_data_warehouse_platform
    where local_date = ${local_date}
    and grass_region in (${grass_region})
    and operation = 'view'
    and original_page_type = 'streaming_room'
    and from_source = 'global_search_srp_live_card_entry'
    and coalesce(live_in_search_request_id, '') <> ''
    and live_in_search_item_id > 0
) t1
inner join ( -- 强限定
    select grass_region
          ,view_event_id as event_id
          ,duration_b_ms -- ms
    from livestream.ls_mart_dwd_view_streaming_detail_di  -- 检查 view_event_id 主键唯一
    where grass_date = ${local_date}
    and grass_region in (${grass_region})
    and viewer_id > 0
) t2
on t1.grass_region = t2.grass_region and t1.event_id = t2.event_id
;

--sql_divide_splitter--
create temporary view l1_union_all_has_location_page_duration_di_${grass_region_without_quote} as -- page_tag = video + minifeed + live
select grass_region
      ,request_id
      ,content_id
      ,location
      ,internal_location
      ,max(page_tag) as page_tag
      ,max(source1_page_tag) as source1_page_tag
      ,sum(duration) as duration
from (
    select grass_region
          ,page_tag
          ,source1_page_tag
          ,request_id
          ,content_id
          ,location
          ,internal_location
          ,duration
    from l1_sr_video_page_duration_di_${grass_region_without_quote}
    where location is not null

    union all
    select grass_region
          ,page_tag
          ,source1_page_tag
          ,request_id
          ,content_id
          ,location
          ,internal_location
          ,duration
    from l1_sr_minifeed_page_duration_di_${grass_region_without_quote}
    where location is not null

    union all
    select grass_region
          ,page_tag
          ,source1_page_tag
          ,request_id
          ,content_id
          ,location
          ,internal_location
          ,duration
    from l1_sr_live_page_duration_di_${grass_region_without_quote}
    where location is not null
) t
group by grass_region, request_id, content_id, location
        ,internal_location -- 冗余维度 internal_location, 数据 click reqid + item + location 关联之后会膨胀一些;
;

--sql_divide_splitter--
create temporary view l1_union_all_no_location_page_duration_di_${grass_region_without_quote} as -- page_tag = video + minifeed + live
select grass_region
      ,request_id
      ,content_id
      ,internal_location
      ,max(page_tag) as page_tag
      ,max(source1_page_tag) as source1_page_tag
      ,sum(duration) as duration
from (
    select grass_region
          ,page_tag
          ,source1_page_tag
          ,request_id
          ,content_id
          ,internal_location
          ,duration
    from l1_sr_video_page_duration_di_${grass_region_without_quote}
    where location is null  -- dd & srp 都增加当前逻辑

    union all
    select grass_region
          ,page_tag
          ,source1_page_tag
          ,request_id
          ,content_id
          ,internal_location
          ,duration
    from l1_sr_minifeed_page_duration_di_${grass_region_without_quote}
    where location is null
    and source1_page_tag = 'dd' -- 只处理dd

    union all
    select grass_region
          ,page_tag
          ,source1_page_tag
          ,request_id
          ,content_id
          ,internal_location
          ,duration
    from l1_sr_live_page_duration_di_${grass_region_without_quote}
    where location is null
    and source1_page_tag = 'srp' -- 只处理srp
) t
group by grass_region, request_id, content_id
        ,internal_location -- 冗余维度 internal_location, 数据 click reqid + item 关联之后会膨胀一些;
;
---------------------------------------------------------------------------------------
-- stage4 -> filter click
---------------------------------------------------------------------------------------
--
--sql_divide_splitter--
create temporary view join_l1_sr_source1_event_${grass_region_without_quote} as
select t1.grass_region
      ,t1.event_id
      ,t1.user_id
      ,t1.click_timestamp

      ,t1.scenario_tag
      ,t1.request_id
      ,t1.item_id
      ,t1.location
      ,t1.card_id
      ,t1.card_type

       ,case
          when t2.pre_click_event_id is not null then t2.internal_location   -- pdp 默认 内流页面location都是0
          when t3.request_id is not null then t3.internal_location
          when t4.request_id is not null then t4.internal_location
          else null
        end as internal_location

       ,case
          when t2.pre_click_event_id is not null then t2.page_tag
          when t3.request_id is not null then t3.page_tag
          when t4.request_id is not null then t4.page_tag
          else null
        end as page_tag

       ,t1.source1_page_tag
       ,null as source2_page_tag

       ,case
          when t2.pre_click_event_id is not null then t2.duration
          when t3.request_id is not null then t3.duration
          when t4.request_id is not null then t4.duration
          else null
        end as duration
from orig_dd_search_click_event_${grass_region_without_quote} t1

left join l1_sr_pdp_page_duration_di_${grass_region_without_quote} t2
on t1.grass_region = t2.grass_region and t1.source1_page_tag = t2.source1_page_tag and t1.event_id = t2.pre_click_event_id

left join l1_union_all_has_location_page_duration_di_${grass_region_without_quote} t3
on t1.grass_region = t3.grass_region and t1.source1_page_tag = t3.source1_page_tag and t1.request_id = t3.request_id and t1.join_content_id = t3.content_id and t1.join_location = t3.location

left join l1_union_all_no_location_page_duration_di_${grass_region_without_quote} t4
on t1.grass_region = t4.grass_region and t1.source1_page_tag = t4.source1_page_tag and t1.request_id = t4.request_id and t1.join_content_id = t4.content_id
;


--sql_divide_splitter--
insert overwrite table ${schema}.dwd_sr_data_warehouse_view_page_duration_di partition(grass_region, local_date, source_level)
select event_id
      ,user_id
      ,click_timestamp

      ,scenario_tag
      ,request_id
      ,item_id
      ,location
      ,card_id
      ,card_type
      ,internal_location

      ,page_tag
      ,source1_page_tag
      ,source2_page_tag
      ,duration

      ,req_click_rn

      ,case
         when page_tag = 'pdp' then 1 -- pdp不需要考虑重复关联数据
         when page_tag is not null and req_click_rn = 1 then 1
         else 0
       end as is_analysis_log

      ,case
         when page_tag = 'pdp' and internal_location = 0 then 1
         when page_tag is not null and req_click_rn = 1 and internal_location = 0 then 1
         else 0
       end as is_sample_log

      ,grass_region
      ,cast(${local_date} as date) as local_date
      ,1 as source_level
from (
    select grass_region
          ,event_id
          ,user_id
          ,click_timestamp

          ,scenario_tag
          ,request_id
          ,item_id
          ,location
          ,card_id
          ,card_type

          ,internal_location
          ,page_tag
          ,source1_page_tag
          ,source2_page_tag
          ,duration

          ,row_number()over(partition by grass_region, source1_page_tag, request_id, item_id, location, internal_location order by click_timestamp asc) as req_click_rn
    from join_l1_sr_source1_event_${grass_region_without_quote}
) t

union all -- 兜底拼接的逻辑, 后续埋点上线, 会删除掉
select t1.event_id
      ,t1.user_id
      ,null as click_timestamp

      ,'dd' as scenario_tag
      ,t1.request_id
      ,null as item_id
      ,null as location
      ,t1.card_id
      ,null as card_type
      ,t1.internal_location

      ,'live' as page_tag
      ,'dd' as source1_page_tag
      ,null as source2_page_tag
      ,cast(t2.duration_b_ms as double) as duration

      ,null as req_click_rn
      ,1 as is_analysis_log
      ,0 as is_sample_log

      ,t1.grass_region
      ,cast(${local_date} as date) as local_date
      ,1 as source_level
from (
    select grass_region
          ,event_id
          ,user_id
          ,request_id
          ,cast(content_id as bigint) as card_id     --  streaming_id
          ,coalesce(location, content_location) as internal_location
    from srdi_mart.dwd_sr_data_warehouse_platform
    where local_date = ${local_date}
    and grass_region in (${grass_region})
    and operation = 'view'
    and original_page_type = 'streaming_room'
    and from_source = 'dd_card'
    and platform in ('ios_app', 'android_app', 'android_app_lite')
    and user_id > 0
    and (coalesce(location, content_location) > 0 or coalesce(location, content_location) is null)
) t1
inner join ( -- 强限定
    select grass_region
          ,view_event_id as event_id
          ,duration_b_ms -- ms
    from livestream.ls_mart_dwd_view_streaming_detail_di  -- 检查 view_event_id 主键唯一
    where grass_date = ${local_date}
    and grass_region in (${grass_region})
    and viewer_id > 0
) t2
on t1.grass_region = t2.grass_region and t1.event_id = t2.event_id
;

