-- canonical_table: srdi_mart.dwd_sr_data_warehouse_view_page_duration_di
-- source_index: 3
-- source_relative_path: analytics-mart-sr-data-warehouse/src/main/resources/dwd/dwd_sr_data_warehouse_view_page_duration_di_l2.sql
-- snapshot_path: data/domains/srdi/snapshots/etl/dwd_sr_data_warehouse_view_page_duration_di/analytics-mart-sr-data-warehouse/src/main/resources/dwd/dwd_sr_data_warehouse_view_page_duration_di_l2.sql
-- deprecated: False
-- sha256: 9f1217c9c38b80c17a747457205bd6c63943dbd7fbd52b48f1926b8d555d2e55
---------------------------------------------------------------------------------------
-- stage1 click source - L2, click主表
---------------------------------------------------------------------------------------
create temporary view orig_dd_search_click_event_${grass_region_without_quote} as
select grass_region
      ,user_id
      ,event_id
      ,log_timestamp as click_timestamp
      ,target_type as card_type

      ,if(original_page_type = 'home', 'dd', 'search') as scenario_tag
      ,request_id
      ,item_id

      ,case
         when target_type in ('item', 'item_mix_feed_card') then item_id
         when target_type in ('video', 'livestream') then cast(content_id as bigint)
         when original_page_type = 'search' and target_type = 'ai_minifeed_card' then null
       end as card_id

      ,location

      ,case
         when original_page_type = 'home' and page_section[0] = 'daily_discover' and target_type = 'livestream' then cast(content_id as bigint) -- 导流到ls没有sv_source_item_id, 使用 streaming_id作为兜底关联键
         when original_page_type = 'search' and page_section[0] is null and target_type = 'ai_minifeed_card' then 0 -- srp minifeed 不上报item_id, 使用 0 作为兜底关联键
         else item_id
       end as join_content_id

      ,case
         when original_page_type = 'home' and page_section[0] = 'daily_discover' and target_type = 'livestream' then 0 -- 导流到ls没解析到 sv_source_location, 使用0作为兜底关联键
         else location
       end as join_location

      ,case
         when original_page_type = 'home' and page_section[0] = 'daily_discover' and target_type in ('video', 'livestream', 'item', 'item_mix_feed_card') then 'dd'
         when original_page_type = 'search' and page_section[0] is null and target_type in ('video', 'livestream', 'item', 'ai_minifeed_card') then 'srp'
       end as source2_page_tag
from srdi_mart.dwd_sr_data_warehouse_platform
where grass_region in (${grass_region})
and local_date = ${local_date}
and operation = 'click'
and original_operation = 'click'
and platform in ('ios_app', 'android_app', 'android_app_lite')
and user_id > 0
and (
         (original_page_type = 'home' and page_section[0] = 'daily_discover' and target_type in ('video', 'livestream', 'item', 'item_mix_feed_card'))
      or
         (original_page_type = 'search' and page_section[0] is null and target_type in ('video', 'livestream', 'item', 'ai_minifeed_card'))
)
;

---------------------------------------------------------------------------------------
-- stage2 类似逻辑近似的 video, minifeed, live 导流页
---------------------------------------------------------------------------------------
--
--sql_divide_splitter--
create temporary view union_all_l2_sr_source1_event_${grass_region_without_quote} as -- page_tag = pdp, source1_page_tag = video_minifeed_live, source2_page_tag = dd & srp
select grass_region
      ,event_id

      ,case
         when sv_source_page = 'iaa_dd_video_card' then split(sv_source_request_id, '\\:')[0] -- 上报数据存在异常, 需要解析兜底下
         when content_type <> 'item' and sv_source_page in ('iaa_srp_video_card') then sv_source_request_id
       end as request_id

      ,sv_source_item_id as content_id
      ,sv_source_location as location
      ,location as internal_location
      ,'video' as source1_page_tag
      ,case
         when sv_source_page = 'iaa_dd_video_card' then 'dd'
         when content_type <> 'item' and sv_source_page in ('iaa_srp_video_card') then 'srp'
       end as source2_page_tag
from srdi_mart.dwd_sr_data_warehouse_platform
where grass_region in (${grass_region})
and local_date = ${local_date}
and operation = 'click'
and original_operation = 'click'
and original_page_type = 'video'
and business_id = '1003'
and (
         sv_source_page = 'iaa_dd_video_card' 							       -- dd->video
      or (content_type <> 'item' and sv_source_page in ('iaa_srp_video_card')) -- srp->video
)
and user_id > 0
and coalesce(sv_source_request_id, '') <> ''
and sv_source_item_id > 0

union all
select grass_region
      ,event_id
      ,sv_source_request_id as request_id
      ,case
         when position_current_page = 'srp_ai_card_page' and sv_source_page = 'iaa_srp_ai_card' then 0
         when position_current_page = 'mix_feed_page' and sv_source_page = 'iaa_dd_mix_item' then sv_source_item_id
       end as content_id
      ,sv_source_location as location
      ,location as internal_location
      ,'minifeed' as source1_page_tag
      ,case
         when position_current_page = 'mix_feed_page' and sv_source_page = 'iaa_dd_mix_item' then 'dd'
         when position_current_page = 'srp_ai_card_page' and sv_source_page = 'iaa_srp_ai_card' then 'srp'
       end as source2_page_tag
from srdi_mart.dwd_sr_data_warehouse_platform
where grass_region in (${grass_region})
and local_date = ${local_date}
and operation = 'click'
and original_operation = 'click'
and original_page_type = 'video'
and (
         (position_current_page = 'mix_feed_page' and sv_source_page = 'iaa_dd_mix_item')       -- dd->minifeed
      or (position_current_page = 'srp_ai_card_page' and sv_source_page = 'iaa_srp_ai_card')    -- srp->minifeed
)
and user_id > 0
and coalesce(sv_source_request_id, '') <> ''

union all  -- dd -> live click
select grass_region
      ,event_id
      ,request_id
      ,cast(ctx_streaming_id as bigint) as content_id     --  streaming_id
      ,0 as location
      ,coalesce(location, content_location) as internal_location

      ,'live' as source1_page_tag
      ,'dd' as source2_page_tag
from srdi_mart.dwd_sr_data_warehouse_platform
where grass_region in (${grass_region})
and local_date = ${local_date}
and operation = 'click'
and original_operation = 'click'
and original_page_type = 'streaming_room'
and ctx_from_source = 'dd_card'
and user_id > 0
and coalesce(request_id, '') <> ''
and cast(ctx_streaming_id as bigint) > 0
and coalesce(location, content_location) = 0 -- 后续新埋点发布之后, 去掉这个限定

union all  -- srp -> live click
select grass_region
      ,event_id
      ,live_in_search_request_id as request_id
      ,live_in_search_item_id as content_id
      ,live_in_search_location as location
      ,coalesce(location, content_location) as internal_location

     ,'live' as source1_page_tag
     ,'srp' as source2_page_tag
from srdi_mart.dwd_sr_data_warehouse_platform
where grass_region in (${grass_region})
and local_date = ${local_date}
and operation = 'click'
and original_operation = 'click'
and original_page_type = 'streaming_room'
and ctx_from_source = 'global_search_srp_live_card_entry'
and user_id > 0
and coalesce(live_in_search_request_id, '') <> ''
and live_in_search_item_id > 0
;

--sql_divide_splitter--
create temporary view l2_sr_page_duration_${grass_region_without_quote} as
select t1.grass_region
      ,t1.request_id
      ,t1.content_id
      ,t1.location
      ,t1.internal_location
      ,'pdp' as page_tag
      ,t1.source1_page_tag
      ,t1.source2_page_tag
      ,cast(t2.duration as double) as duration
from union_all_l2_sr_source1_event_${grass_region_without_quote} t1
inner join ( -- 强限定
    select grass_region
          ,position_info.pre_click_event_id as pre_click_event_id
          ,sum(page_duration) as duration -- ms
    from traffic.dwd_view_di__reg_live
    where grass_date =  ${local_date}
    and grass_region in (${grass_region})
    and tz_type = 'local'
    and os in ('ios', 'android')
    and page_type = 'product'
    and (pre_position_code like 'video.%' or pre_position_code like 'streaming_room.%')
    and user_id > 0
    and coalesce(position_info.pre_click_event_id, '') <> ''
    group by grass_region, position_info.pre_click_event_id
) t2
on t1.grass_region = t2.grass_region and t1.event_id = t2.pre_click_event_id
;

--sql_divide_splitter--
create temporary view l2_sr_has_location_page_duration_${grass_region_without_quote} as
select grass_region
      ,request_id
      ,content_id
      ,location
      ,internal_location
      ,max(page_tag) as page_tag
      ,max(source1_page_tag) as source1_page_tag
      ,max(source2_page_tag) as source2_page_tag
      ,sum(duration) as duration
from l2_sr_page_duration_${grass_region_without_quote}
where location is not null
group by grass_region, request_id, content_id, location
        ,internal_location -- 冗余维度 internal_location, 数据 click reqid + item + location 关联之后会膨胀一些;
;

--sql_divide_splitter--
create temporary view l2_sr_no_location_page_duration_${grass_region_without_quote} as
select grass_region
      ,request_id
      ,content_id
      ,internal_location
      ,max(page_tag) as page_tag
      ,max(source1_page_tag) as source1_page_tag
      ,max(source2_page_tag) as source2_page_tag
      ,sum(duration) as duration
from l2_sr_page_duration_${grass_region_without_quote}
where location is null
and (
         source1_page_tag = 'video'
     or (source1_page_tag = 'minifeed' and source2_page_tag = 'dd')
     or (source1_page_tag = 'live' and source2_page_tag = 'srp')
)
group by grass_region, request_id, content_id
        ,internal_location -- 冗余维度 internal_location, 数据 click reqid + item 关联之后会膨胀一些;
;

---------------------------------------------------------------------------------------
-- stage3 -> filter click
---------------------------------------------------------------------------------------
--
--sql_divide_splitter--
create temporary view join_l2_sr_source1_event_${grass_region_without_quote} as
select t1.grass_region
      ,t1.event_id
      ,t1.user_id
      ,t1.click_timestamp

      ,t1.scenario_tag
      ,t1.request_id
      ,t1.item_id
      ,t1.location
      ,t1.card_id
      ,t1.card_type

      ,case
         when t2.request_id is not null then t2.internal_location
         when t3.request_id is not null then t3.internal_location
         else null
       end internal_location

      ,case
         when t2.request_id is not null then t2.page_tag
         when t3.request_id is not null then t3.page_tag
         else null
       end page_tag

      ,case
         when t2.request_id is not null then t2.source1_page_tag
         when t3.request_id is not null then t3.source1_page_tag
         else null
       end source1_page_tag

      ,t1.source2_page_tag

      ,case
         when t2.request_id is not null then t2.duration
         when t3.request_id is not null then t3.duration
         else null
       end duration
from orig_dd_search_click_event_${grass_region_without_quote} t1

left join l2_sr_has_location_page_duration_${grass_region_without_quote} t2
on t1.grass_region = t2.grass_region and t1.source2_page_tag = t2.source2_page_tag and t1.request_id = t2.request_id and t1.join_content_id = t2.content_id and t1.join_location = t2.location

left join l2_sr_no_location_page_duration_${grass_region_without_quote} t3
on t1.grass_region = t3.grass_region and t1.source2_page_tag = t3.source2_page_tag and t1.request_id = t3.request_id and t1.join_content_id = t3.content_id
;


--sql_divide_splitter--
insert overwrite table ${schema}.dwd_sr_data_warehouse_view_page_duration_di partition(grass_region, local_date, source_level)
select event_id
      ,user_id
      ,click_timestamp

      ,scenario_tag
      ,request_id
      ,item_id
      ,location
      ,card_id
      ,card_type
      ,internal_location

      ,page_tag
      ,source1_page_tag
      ,source2_page_tag
      ,duration

      ,req_click_rn
      ,if(page_tag is not null and req_click_rn = 1, 1, 0) as is_analysis_log
      ,if(page_tag is not null and req_click_rn = 1 and internal_location = 0, 1, 0) as is_sample_log

      ,grass_region
      ,cast(${local_date} as date) as local_date
      ,2 as source_level
from (
    select grass_region
          ,event_id
          ,user_id
          ,click_timestamp

          ,scenario_tag
          ,request_id
          ,item_id
          ,location
          ,card_id
          ,card_type

          ,internal_location
          ,page_tag
          ,source1_page_tag
          ,source2_page_tag
          ,duration

          ,row_number()over(partition by grass_region, source2_page_tag, request_id, item_id, location, internal_location order by click_timestamp asc) as req_click_rn
    from join_l2_sr_source1_event_${grass_region_without_quote}
) t

union all -- 兜底拼接的逻辑, 后续埋点上线, 会删除掉
select t1.event_id
      ,t1.user_id
      ,null as click_timestamp

      ,'dd' as scenario_tag
      ,t1.request_id
      ,null as item_id
      ,null as location
      ,t1.card_id
      ,null as card_type
      ,t1.internal_location

      ,'pdp' as page_tag
      ,'live' as source1_page_tag
      ,'dd' as source2_page_tag
      ,cast(t2.duration as double) as duration

      ,null as req_click_rn
      ,1 as is_analysis_log
      ,0 as is_sample_log

      ,t1.grass_region
      ,cast(${local_date} as date) as local_date
      ,2 as source_level
from (
    select grass_region
          ,event_id
          ,user_id
          ,request_id
          ,cast(ctx_streaming_id as bigint) as card_id     --  streaming_id
          ,coalesce(location, content_location) as internal_location
    from srdi_mart.dwd_sr_data_warehouse_platform
    where grass_region in (${grass_region})
    and local_date = ${local_date}
    and operation = 'click'
    and original_operation = 'click'
    and original_page_type = 'streaming_room'
    and ctx_from_source = 'dd_card'
    and platform in ('ios_app', 'android_app', 'android_app_lite')
    and user_id > 0
    and (coalesce(location, content_location) > 0 or coalesce(location, content_location) is null)
) t1
inner join ( -- 强限定
    select grass_region
          ,position_info.pre_click_event_id as pre_click_event_id
          ,sum(page_duration) as duration -- ms
    from traffic.dwd_view_di__reg_live
    where grass_date =  ${local_date}
    and grass_region in (${grass_region})
    and tz_type = 'local'
    and os in ('ios', 'android')
    and page_type = 'product'
    and pre_position_code like 'streaming_room.%'
    and user_id > 0
    and coalesce(position_info.pre_click_event_id, '') <> ''
    group by grass_region, position_info.pre_click_event_id
) t2
on t1.grass_region = t2.grass_region and t1.event_id = t2.pre_click_event_id
;
